import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_conv_transpose3d(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int groups);
"""


cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void cute_conv_transpose3d_kernel(
    const float* __restrict__ x_ptr,
    const float* __restrict__ w_ptr,
    const float* __restrict__ b_ptr,
    float* __restrict__ y_ptr,
    int N,
    int IC,
    int ID,
    int IH,
    int IW,
    int OC,
    int OCG,
    int OD,
    int OH,
    int OW,
    int K,
    int stride,
    int padding,
    int groups,
    bool has_bias)
{
    constexpr int TILE_OC = 8;
    constexpr int TILE_SPATIAL = 64;
    const int tid = threadIdx.x;
    const int spatial_local = tid / TILE_OC;
    const int oc_local = tid % TILE_OC;
    const int n = blockIdx.z;
    const int spatial_base = blockIdx.x * TILE_SPATIAL;
    const int oc_base = blockIdx.y * TILE_OC;
    const int oc = oc_base + oc_local;
    const int spatial0 = spatial_base + spatial_local * 2;
    const int spatial1 = spatial0 + 1;
    const bool valid0 = n < N && spatial0 < OD * OH * OW && oc < OC;
    const bool valid1 = n < N && spatial1 < OD * OH * OW && oc < OC;
    auto gX = make_tensor(
        make_gmem_ptr(x_ptr),
        make_shape(N, IC, ID, IH, IW),
        make_stride(
            IC * ID * IH * IW,
            ID * IH * IW,
            IH * IW,
            IW,
            1));
    auto gW = make_tensor(
        make_gmem_ptr(w_ptr),
        make_shape(IC, OCG, K, K, K),
        make_stride(
            OCG * K * K * K,
            K * K * K,
            K * K,
            K,
            1));
    auto gY = make_tensor(
        make_gmem_ptr(y_ptr),
        make_shape(N, OC, OD, OH, OW),
        make_stride(
            OC * OD * OH * OW,
            OD * OH * OW,
            OH * OW,
            OW,
            1));
    auto gB = make_tensor(
        make_gmem_ptr(b_ptr),
        make_shape(OC),
        make_stride(1));
    float acc0 = (valid0 && has_bias) ? gB(oc) : 0.0f;
    float acc1 = (valid1 && has_bias) ? gB(oc) : 0.0f;
    const int K3 = K * K * K;
    extern __shared__ float smem[];
    float* smem_x = smem;
    float* smem_w = smem + TILE_SPATIAL * K3;
    if (groups == 1) {
        const int input_count = TILE_SPATIAL * K3;
        const int weight_count = TILE_OC * K3;
        for (int ic = 0; ic < IC; ++ic) {
            for (int q = tid; q < input_count; q += blockDim.x) {
                const int spatial_q = q / K3;
                const int kq = q - spatial_q * K3;
                const int kd = kq / (K * K);
                const int kr = kq - kd * K * K;
                const int kh = kr / K;
                const int kw = kr - kh * K;
                const int out_spatial = spatial_base + spatial_q;
                float value = 0.0f;
                if (n < N && out_spatial < OD * OH * OW) {
                    const int plane = OH * OW;
                    const int oz = out_spatial / plane;
                    const int rem = out_spatial - oz * plane;
                    const int oy = rem / OW;
                    const int ox = rem - oy * OW;
                    const int zd = oz + padding - kd;
                    const int yh = oy + padding - kh;
                    const int xw = ox + padding - kw;
                    if (zd >= 0 && zd % stride == 0 &&
                        yh >= 0 && yh % stride == 0 &&
                        xw >= 0 && xw % stride == 0) {
                        const int iz = zd / stride;
                        const int iy = yh / stride;
                        const int ix = xw / stride;
                        if (iz < ID && iy < IH && ix < IW)
                            value = gX(n, ic, iz, iy, ix);
                    }
                }
                smem_x[q] = value;
            }
            for (int q = tid; q < weight_count; q += blockDim.x) {
                const int tile_oc = q / K3;
                const int kq = q - tile_oc * K3;
                const int kd = kq / (K * K);
                const int kr = kq - kd * K * K;
                const int kh = kr / K;
                const int kw = kr - kh * K;
                const int global_oc = oc_base + tile_oc;
                smem_w[q] = global_oc < OC
                    ? gW(ic, global_oc, kd, kh, kw)
                    : 0.0f;
            }
            __syncthreads();
            if (valid0 || valid1) {
                const int wbase = oc_local * K3;
                if (valid0) {
                    const int xbase = (spatial_local * 2) * K3;
                    for (int kq = 0; kq < K3; ++kq)
                        acc0 += smem_x[xbase + kq] * smem_w[wbase + kq];
                }
                if (valid1) {
                    const int xbase = (spatial_local * 2 + 1) * K3;
                    for (int kq = 0; kq < K3; ++kq)
                        acc1 += smem_x[xbase + kq] * smem_w[wbase + kq];
                }
            }
            __syncthreads();
        }
    } else {
        const int group = oc / OCG;
        const int ic_per_group = IC / groups;
        const int ic_begin = group * ic_per_group;
        const int ic_end = ic_begin + ic_per_group;
        for (int r = 0; r < 2; ++r) {
            const int spatial = r == 0 ? spatial0 : spatial1;
            const bool valid = r == 0 ? valid0 : valid1;
            float acc = (valid && has_bias) ? gB(oc) : 0.0f;
            if (valid) {
                const int plane = OH * OW;
                const int oz = spatial / plane;
                const int rem = spatial - oz * plane;
                const int oy = rem / OW;
                const int ox = rem - oy * OW;
                for (int ic = ic_begin; ic < ic_end; ++ic)
                    for (int kd = 0; kd < K; ++kd) {
                        const int zd = oz + padding - kd;
                        if (zd < 0 || zd % stride != 0 || zd / stride >= ID) continue;
                        for (int kh = 0; kh < K; ++kh) {
                            const int yh = oy + padding - kh;
                            if (yh < 0 || yh % stride != 0 || yh / stride >= IH) continue;
                            for (int kw = 0; kw < K; ++kw) {
                                const int xw = ox + padding - kw;
                                if (xw < 0 || xw % stride != 0 || xw / stride >= IW) continue;
                                acc += gX(n, ic, zd / stride, yh / stride, xw / stride) *
                                       gW(ic, oc - group * OCG, kd, kh, kw);
                            }
                        }
                    }
            }
            if (valid) gY(n, oc, spatial / (OH * OW),
                           (spatial % (OH * OW)) / OW, spatial % OW) = acc;
        }
    }
    if (valid0)
        gY(n, oc, spatial0 / (OH * OW),
           (spatial0 % (OH * OW)) / OW, spatial0 % OW) = acc0;
    if (valid1)
        gY(n, oc, spatial1 / (OH * OW),
           (spatial1 % (OH * OW)) / OW, spatial1 % OW) = acc1;
}
torch::Tensor cute_conv_transpose3d(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int groups)
{
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(x.dim() == 5, "x must be 5D");
    TORCH_CHECK(weight.dim() == 5, "weight must be 5D");
    TORCH_CHECK(stride > 0, "stride must be positive");
    TORCH_CHECK(groups > 0, "groups must be positive");

    const int N = static_cast<int>(x.size(0));
    const int IC = static_cast<int>(x.size(1));
    const int ID = static_cast<int>(x.size(2));
    const int IH = static_cast<int>(x.size(3));
    const int IW = static_cast<int>(x.size(4));

    const int OCG = static_cast<int>(weight.size(1));
    const int K = static_cast<int>(weight.size(2));
    const int OC = OCG * groups;

    TORCH_CHECK(weight.size(0) == IC, "Invalid weight input-channel dimension");
    TORCH_CHECK(weight.size(3) == K && weight.size(4) == K,
                "Only cubic kernels are supported");
    TORCH_CHECK(IC % groups == 0, "Input channels must be divisible by groups");

    if (bias.defined() && bias.numel() > 0) {
        TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");
        TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");
        TORCH_CHECK(bias.numel() == OC, "Invalid bias size");
    }

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();

    torch::Tensor b_c;
    bool has_bias = bias.defined() && bias.numel() > 0;
    if (has_bias) {
        b_c = bias.contiguous();
    } else {
        b_c = torch::empty({OC}, x.options());
    }

    const int OD = (ID - 1) * stride - 2 * padding + K + output_padding;
    const int OH = (IH - 1) * stride - 2 * padding + K + output_padding;
    const int OW = (IW - 1) * stride - 2 * padding + K + output_padding;

    TORCH_CHECK(OD >= 0 && OH >= 0 && OW >= 0,
                "Invalid transposed convolution output size");

    auto y = torch::empty({N, OC, OD, OH, OW}, x.options());

    constexpr int THREADS = 256;
    const int spatial_tiles = (OD * OH * OW + 63) / 64;
    const int oc_tiles = (OC + 7) / 8;
    dim3 block(THREADS);
    dim3 grid(spatial_tiles, oc_tiles, N);
    const size_t shared_bytes =
        static_cast<size_t>((64 + 8) * K * K * K * sizeof(float));

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_conv_transpose3d_kernel<<<grid, block, shared_bytes, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_c.data_ptr<float>(),
        y.data_ptr<float>(),
        N,
        IC,
        ID,
        IH,
        IW,
        OC,
        OCG,
        OD,
        OH,
        OW,
        K,
        stride,
        padding,
        groups,
        has_bias);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess,
                "CUTE ConvTranspose3d kernel launch failed");

    return y;
}
"""


cute_ext = load_inline(
    name="cute_conv_transpose3d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_conv_transpose3d"],
    extra_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        output_padding: int = 0,
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()

        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels,
            out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride,
            padding=padding,
            output_padding=output_padding,
            groups=groups,
            bias=bias,
        )

        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias = self.conv_transpose3d.bias
        if bias is None:
            bias = torch.empty(
                0,
                device=x.device,
                dtype=x.dtype,
            )

        return cute_ext.cute_conv_transpose3d(
            x,
            self.conv_transpose3d.weight,
            bias,
            self.stride,
            self.padding,
            self.output_padding,
            self.groups,
        )

