class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        output_padding: int = 0,
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()

        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels,
            out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride,
            padding=padding,
            output_padding=output_padding,
            groups=groups,
            bias=bias,
        )

        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias = self.conv_transpose3d.bias
        if bias is None:
            bias = torch.empty(
                0,
                device=x.device,
                dtype=x.dtype,
            )

        return cute_ext.cute_conv_transpose3d(
            x,
            self.conv_transpose3d.weight,
            bias,
            self.stride,
            self.padding,
            self.output_padding,
            self.groups,
        )
